#include <bits/stdc++.h>
#define ll long long
using namespace std;
const ll MOD1 = 998244353;
const ll MOD2 = 1000000007;
ll answer;
ll total;
ll count1;
vector<ll> values[7];
ll totalSum[7];

void generateValues(int level, ll currentNumber) {
    if (level == 7) return;
    values[level].push_back((total - currentNumber + MOD1) % MOD1);
    totalSum[level] += (total - currentNumber + MOD1) % MOD1;
    ++total;
    for (int digit = 0; digit <= 9; ++digit)
        generateValues(level + 1, currentNumber * 10 + digit);
}

inline bool isInRange(ll x) { return x * 1000000 + 999999 <= total && x * 10000000 > total; }

ll count2;
ll powers[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

void explore(ll level, ll number) {
    if (number > total) return;
    if (isInRange(number)) {
        for (int i = 0; i <= 6; ++i) {
            ll offset = ((count2 + 1 - (number * powers[i])) % MOD1 + MOD1) % MOD1;
            auto pos = lower_bound(values[i].begin(), values[i].end(), MOD1 - offset) - values[i].begin();
            answer = (answer + (totalSum[i] + offset * (ll)values[i].size() - MOD1 * ((ll)values[i].size() - pos))) % MOD2;
        }
        count2 += count1;
    } else {
        ++count2;
        answer = (answer + ((count2 - number) % MOD1 + MOD1) % MOD1) % MOD2;
        for (int digit = (!level); digit <= 9; ++digit)
            explore(level + 1, number * 10 + digit);
    }
}

int main() {
    cin >> total;
    generateValues(0, 0);
    for (int i = 0; i <= 6; ++i) sort(values[i].begin(), values[i].end());
    count2 = -1;
    explore(0, 0);
    cout << answer << "\n";
}
